CREATE TABLE IF NOT EXISTS rollback_records ( id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), checkpoint_id TEXT NOT NULL REFERENCES checkpoints(id), reason TEXT NOT NULL, status TEXT NOT NULL, restored_hash TEXT, created_at BIGINT NOT NULL );
CREATE TABLE IF NOT EXISTS telemetry ( id TEXT PRIMARY KEY, tenant_id TEXT REFERENCES tenants(id), node_id TEXT, metric TEXT NOT NULL, value DOUBLE PRECISION NOT NULL, unit TEXT, recorded_at BIGINT NOT NULL );
CREATE TABLE IF NOT EXISTS audit_records ( id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), index_num BIGINT NOT NULL, actor TEXT NOT NULL, action TEXT NOT NULL, target_entity TEXT NOT NULL, target_id TEXT NOT NULL, payload_json TEXT NOT NULL, payload_hash TEXT NOT NULL, previous_hash TEXT NOT NULL, record_hash TEXT NOT NULL UNIQUE, created_at BIGINT NOT NULL, UNIQUE (tenant_id, index_num) );
CREATE TABLE IF NOT EXISTS chain_records ( id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), audit_record_id TEXT NOT NULL REFERENCES audit_records(id), chain_height BIGINT NOT NULL, merkle_root TEXT NOT NULL, created_at BIGINT NOT NULL );
CREATE TABLE IF NOT EXISTS licenses ( id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), solution_id TEXT NOT NULL REFERENCES solutions(id), order_id TEXT REFERENCES orders(id), license_key_hash TEXT NOT NULL UNIQUE, status TEXT NOT NULL DEFAULT 'ACTIVE', issued_at BIGINT NOT NULL, expires_at BIGINT );
CREATE TABLE IF NOT EXISTS adapter_status ( id TEXT PRIMARY KEY, tenant_id TEXT REFERENCES tenants(id), adapter_name TEXT NOT NULL, provider TEXT NOT NULL, environment TEXT NOT NULL, status TEXT NOT NULL, last_error TEXT, checked_at BIGINT NOT NULL );
CREATE TABLE IF NOT EXISTS node_registry ( id TEXT PRIMARY KEY, node_code TEXT NOT NULL UNIQUE, node_name TEXT NOT NULL, subsystem TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'REGISTERED', capabilities_json TEXT NOT NULL DEFAULT '[]', created_at BIGINT NOT NULL );
CREATE TABLE IF NOT EXISTS execution_runs ( id TEXT PRIMARY KEY, tenant_id TEXT REFERENCES tenants(id), run_type TEXT NOT NULL, target_id TEXT, status TEXT NOT NULL, input_hash TEXT, output_hash TEXT, evidence_hash TEXT, started_at BIGINT NOT NULL, completed_at BIGINT );
CREATE TABLE IF NOT EXISTS failures ( id TEXT PRIMARY KEY, tenant_id TEXT REFERENCES tenants(id), execution_run_id TEXT REFERENCES execution_runs(id), failure_type TEXT NOT NULL, severity TEXT NOT NULL, message TEXT NOT NULL, quarantined BOOLEAN NOT NULL DEFAULT TRUE, resolved_at BIGINT, created_at BIGINT NOT NULL );
ALTER TABLE orders ADD CONSTRAINT orders_payment_id_fkey FOREIGN KEY (payment_id) REFERENCES payments(id);
ALTER TABLE orders ADD CONSTRAINT orders_deployment_id_fkey FOREIGN KEY (deployment_id) REFERENCES deployments(id);
CREATE INDEX IF NOT EXISTS idx_users_tenant ON users(tenant_id);
CREATE INDEX IF NOT EXISTS idx_problems_tenant ON problems(tenant_id);
CREATE INDEX IF NOT EXISTS idx_solutions_tenant ON solutions(tenant_id);
CREATE INDEX IF NOT EXISTS idx_offers_tenant ON offers(tenant_id);
CREATE INDEX IF NOT EXISTS idx_orders_tenant ON orders(tenant_id);
CREATE INDEX IF NOT EXISTS idx_audit_tenant_height ON audit_records(tenant_id, index_num);
CREATE INDEX IF NOT EXISTS idx_execution_runs_tenant ON execution_runs(tenant_id);
CREATE INDEX IF NOT EXISTS idx_telemetry_node_time ON telemetry(node_id, recorded_at);
